# owner: platform
"""Plain text absence notices for parents."""

from typing import Iterable, List

from rosterkit.models import Mark, Student


def _absent_days(marks: List[Mark]) -> list:
    """Sorted, distinct days marked absent."""
    return sorted({m.day for m in marks if m.status == "absent"})


def _check_owner(student: Student, marks: List[Mark]):
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for {mark.student_id} does not "
                f"belong to {student.student_id}"
            )


def _long_date(day) -> str:
    return f"{day:%B} {day.day}, {day.year}"


# ---
def build_absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Notice naming the student, days missed and the dates."""
    marks = list(marks)
    _check_owner(student, marks)
    days = _absent_days(marks)
    if not days:
        raise ValueError("no absences to write a notice about")
    return _compose(student, days)


def _compose(student: Student, days: list) -> str:
    name = f"{student.first_name} {student.last_name}"
    word = "day" if len(days) == 1 else "days"
    dates = "\n".join(f"- {_long_date(d)}" for d in days)
    return (
        f"{name} missed {len(days)} {word} of school:\n"
        f"{dates}"
    )
EOF
cat > tests/test_notices.py <<'EOF'
# owner: platform
import unittest
from datetime import date

from rosterkit.models import Mark, Student
from rosterkit.notices import build_absence_notice

PUPIL = Student("7", "Rivera", "Ana", "A")


def mark(day, status="absent", pupil="7"):
    return Mark(pupil, date(2026, 10, day), status)


class NoticeTests(unittest.TestCase):
    def test_lists_absent_dates_in_order(self):
        marks = [mark(9), mark(5), mark(6, "present")]
        text = build_absence_notice(PUPIL, marks)
        self.assertIn("Ana Rivera missed 2 days", text)
        first = text.index("October 5, 2026")
        self.assertLess(first, text.index("October 9, 2026"))
        self.assertNotIn("October 6", text)

    def test_single_day_is_singular(self):
        text = build_absence_notice(PUPIL, [mark(5)])
        self.assertIn("missed 1 day ", text)

    def test_other_student_is_rejected(self):
        marks = [mark(5), mark(6, pupil="8")]
        with self.assertRaises(ValueError):
            build_absence_notice(PUPIL, marks)

    def test_no_absences_is_rejected(self):
        marks = [mark(5, "late"), mark(6, "excused")]
        with self.assertRaises(ValueError):
            build_absence_notice(PUPIL, marks)
EOF
ROSTERKIT_ENV=test python3 -m unittest discover -s tests 2>&1 | tail -5; python3 tools/lint.py; awk 'length>60' rosterkit/notices.py tests/test_notices.py

